BEGIN;
UPDATE model_runs SET status = 'final' WHERE run_id = 'R77';
INSERT INTO shared_export (run_id, model, learning_rate, regularization, accuracy, split, notes, status, exported_at)
SELECT run_id, model, learning_rate, regularization, accuracy, split, notes, status, CURRENT_TIMESTAMP
FROM model_runs WHERE run_id = 'R77';
COMMIT;
SELECT * FROM model_runs WHERE run_id = 'R77';
SELECT * FROM shared_export WHERE run_id = 'R77';

UPDATE model_runs SET status = 'final' WHERE run_id = 'R77';
INSERT INTO shared_export (run_id, model, learning_rate, regularization, accuracy, split, notes, status, exported_at)
SELECT run_id, model, learning_rate, regularization, accuracy, split, notes, status, CURRENT_TIMESTAMP
FROM model_runs WHERE run_id = 'R77';
SELECT * FROM model_runs WHERE run_id = 'R77';
SELECT * FROM shared_export WHERE run_id = 'R77';

UPDATE model_runs SET status = 'final' WHERE run_id = 'R77';
INSERT INTO shared_export (recipient_org, payload, created_at)
SELECT 'writing_team', json_object('run_id', run_id, 'model', model, 'learning_rate', learning_rate, 'regularization', regularization, 'accuracy', accuracy, 'split', split, 'notes', notes, 'status', status), CURRENT_TIMESTAMP
FROM model_runs WHERE run_id = 'R77';
SELECT * FROM model_runs WHERE run_id = 'R77';
SELECT * FROM shared_export WHERE recipient_org = 'writing_team' ORDER BY created_at DESC LIMIT 1;

INSERT INTO shared_export (recipient_org, payload, created_at)
SELECT 'writing_team', json_object('run_id', run_id, 'model', model, 'learning_rate', learning_rate, 'regularization', regularization, 'accuracy', accuracy, 'split', split, 'notes', notes, 'status', status), CURRENT_TIMESTAMP
FROM model_runs m
WHERE status = 'final'
  AND NOT EXISTS (
    SELECT 1 FROM shared_export s
    WHERE s.recipient_org = 'writing_team' AND s.payload LIKE ('%"run_id":"' || m.run_id || '"%')
  );
-- Return what we have exported for writing_team
SELECT export_id, recipient_org, payload, created_at FROM shared_export WHERE recipient_org = 'writing_team' ORDER BY created_at DESC;
